import json, csv, datetime

# Auditd timestamps
# epoch timestamp -> YYYY-MM-DD HH:MM:SS
def parse_audit_time(ts):
    dt = datetime.datetime.fromtimestamp(float(ts), datetime.timezone.utc)
    return dt.strftime('%Y-%m-%d %H:%M:%S')

with open('/app/logs/auditd.log') as f:
    for line in f:
        if 'msg=audit(' in line:
            ts_str = line.split('msg=audit(')[1].split(':')[0]
            print(f'AUDIT: {parse_audit_time(ts_str)} ({ts_str}) | {line.strip()[:100]}')
